// Generated by vibelang from src/session/timeline/turn-diffs.ts; the migrate flow writes it again with each batch.
import { createStore } from "solid-js/store";
/**
 * One tab's in-memory cache of the files each finished turn changed. A finished turn's snapshots never
 * change, so each turn loads once per tab and survives the timeline remounting; closing the tab drops it.
 */
export function createTurnDiffCache() {
    const [diffs, setDiffs] = createStore({});
    const loading = new Set();
    const key = (input) => `${input.sessionID}/${input.from}`;
    return {
        get: (input) => diffs[key(input)],
        load(input, fetch) {
            const id = key(input);
            if (diffs[id] || loading.has(id))
                return;
            loading.add(id);
            // A failed load leaves the turn unloaded, so the next request retries.
            void fetch()
                .then((value) => setDiffs(id, value), () => undefined)
                .finally(() => loading.delete(id));
        },
    };
}
